﻿#pragma once

/**
 * @file MyPaintDlg.h
 * @brief 주 대화 상자 클래스 선언
 */

#include "CanvasWnd.h"
#include "ColorPalette.h"

#include <array>

/**
 * @brief 주 대화 상자.
 *
 * 위쪽 도구 모음(도구 / 모양 / 색), 가운데 캔버스, 아래쪽 상태 표시줄로 구성됩니다.
 * 컨트롤은 DPI에 맞춰 코드에서 만들고 배치합니다.
 */
class CMyPaintDlg : public CDialog
{
public:
    /**
     * @brief 생성자
     * @param pParent 부모 창 (없으면 nullptr)
     */
    explicit CMyPaintDlg(CWnd* pParent = nullptr);

#ifdef AFX_DESIGN_TIME
    enum { IDD = IDD_MYPAINT_DIALOG };
#endif

protected:
    /**
     * @brief 컨트롤과 멤버 변수 사이의 데이터 교환
     * @param pDX 데이터 교환 개체
     */
    void DoDataExchange(CDataExchange* pDX) override;

    /**
     * @brief 대화 상자 초기화
     * @return 포커스를 컨트롤에 직접 지정하지 않으면 TRUE
     */
    BOOL OnInitDialog() override;

    /** @brief Enter 키로 대화 상자가 닫히지 않게 합니다. */
    void OnOK() override;

    /** @brief Esc 키: 그리는 중이면 취소하고, 대화 상자는 닫지 않습니다. */
    void OnCancel() override;

    afx_msg void OnClose();
    afx_msg void OnPaint();
    afx_msg void OnSize(UINT nType, int cx, int cy);
    afx_msg void OnGetMinMaxInfo(MINMAXINFO* lpMMI);
    afx_msg LRESULT OnDpiChanged(WPARAM wParam, LPARAM lParam);
    afx_msg void OnToolButton(UINT nID);
    afx_msg void OnSizeComboChanged();
    afx_msg void OnFillComboChanged();
    afx_msg void OnEditColor();
    afx_msg LRESULT OnCanvasCursor(WPARAM wParam, LPARAM lParam);
    afx_msg LRESULT OnCanvasColorPicked(WPARAM wParam, LPARAM lParam);
    afx_msg LRESULT OnPaletteColorChanged(WPARAM wParam, LPARAM lParam);
    DECLARE_MESSAGE_MAP()

private:
    /** @brief 도구 모음의 묶음 */
    enum Group
    {
        GroupTools,
        GroupShape,
        GroupColors,
        GroupCount,
    };

    /** @brief 현재 DPI에 맞춘 픽셀 수 (96 DPI 기준 값을 받음) */
    int Scale(int value) const;

    /** @brief 현재 DPI의 메시지 글꼴을 만들어 모든 컨트롤에 적용합니다. */
    void UpdateUiFont();

    void CreateControls();
    void LayoutControls();

    /** @brief 도구를 고르고 도구 버튼과 옵션 컨트롤을 맞춥니다. */
    void SelectTool(ToolType tool);
    /** @brief 현재 도구에 맞게 굵기, 채우기 컨트롤을 갱신합니다. */
    void UpdateToolOptions();
    /** @brief 팔레트의 색을 캔버스에 반영합니다. */
    void SyncColorsToCanvas();
    void UpdateImageSizeStatus();

    HICON m_hIcon = nullptr; ///< 창 아이콘
    UINT m_dpi = USER_DEFAULT_SCREEN_DPI;
    CFont m_font;            ///< 컨트롤 글꼴 (현재 DPI)

    CCanvasWnd m_canvas;
    CColorPalette m_palette;
    std::array<CButton, kToolCount> m_toolButtons;
    CStatic m_sizeLabel;
    CComboBox m_sizeCombo;
    CStatic m_fillLabel;
    CComboBox m_fillCombo;
    CButton m_editColorButton;
    CStatusBarCtrl m_statusBar;

    ToolType m_toolBeforePicker = ToolType::Pencil; ///< 스포이트로 색을 집은 뒤 돌아갈 도구

    // 배치 결과 (OnPaint에서 묶음 이름과 구분선을 그릴 때 씀)
    std::array<CRect, GroupCount> m_groupRects;     ///< 묶음별 컨트롤 영역
    int m_captionTop = 0;                           ///< 묶음 이름 위쪽 y
    int m_bandBottom = 0;                           ///< 도구 모음 아래쪽 y
    int m_minClientWidth = 0;                       ///< 도구 모음이 잘리지 않는 최소 너비
};
#pragma once

/**
 * @file CanvasWnd.h
 * @brief 그림을 보여 주고 마우스로 그리게 하는 캔버스 창
 */

#include "CanvasSurface.h"
#include "PaintTools.h"

#include <array>
#include <memory>

/**
 * @brief 캔버스 창.
 *
 * 그림(CCanvasSurface)과 현재 도구, 색, 굵기를 가지고, 마우스 입력을 도구에 전달합니다.
 * 그림이 창보다 크면 스크롤 막대로 이동합니다. 그리기 상태가 바뀌면 부모 창에
 * WM_CANVAS_CURSOR, WM_CANVAS_COLORPICKED 메시지를 보냅니다.
 */
class CCanvasWnd : public CWnd, private IToolHost
{
public:
    CCanvasWnd();
    ~CCanvasWnd() override;

    /**
     * @brief 창을 만듭니다.
     * @param rect 부모 클라이언트 좌표의 위치
     * @param pParent 부모 창
     * @param nID 컨트롤 ID
     * @return 성공하면 TRUE
     */
    BOOL Create(const CRect& rect, CWnd* pParent, UINT nID);

    /**
     * @brief 지정한 크기의 흰 그림으로 새로 시작합니다.
     * @return 성공하면 true
     */
    bool NewImage(int width, int height);

    /** @brief 그림 크기(px) */
    CSize GetImageSize() const { return m_surface.GetSize(); }

    /** @brief 현재 도구를 바꿉니다. 그리는 중이었다면 취소합니다. */
    void SetTool(ToolType tool);
    /** @brief 현재 도구 */
    ToolType GetTool() const { return m_tool; }

    /** @brief 도구별 굵기를 정합니다. */
    void SetToolSize(ToolType tool, int size);
    /** @brief 도구별 굵기 */
    int GetToolSize(ToolType tool) const { return m_toolSizes[ToIndex(tool)]; }

    /** @brief 도형 채우기 방식을 정합니다. */
    void SetFillMode(ShapeFillMode mode) { m_fillMode = mode; }
    /** @brief 도형 채우기 방식 */
    ShapeFillMode GetFillMode() const { return m_fillMode; }

    /**
     * @brief 그리기 색을 정합니다.
     * @param primary 색 1 (왼쪽 버튼)
     * @param secondary 색 2 (오른쪽 버튼, 지우개)
     */
    void SetColors(COLORREF primary, COLORREF secondary);

    /** @brief 진행 중인 그리기를 취소하고 그림을 시작 전 상태로 되돌립니다. */
    void CancelStroke();

    /** @brief 마우스로 그리는 중이면 true */
    bool IsStroking() const { return m_stroking; }

protected:
    afx_msg void OnPaint();
    afx_msg BOOL OnEraseBkgnd(CDC* pDC);
    afx_msg void OnSize(UINT nType, int cx, int cy);
    afx_msg void OnHScroll(UINT nSBCode, UINT nPos, CScrollBar* pScrollBar);
    afx_msg void OnVScroll(UINT nSBCode, UINT nPos, CScrollBar* pScrollBar);
    afx_msg BOOL OnMouseWheel(UINT nFlags, short zDelta, CPoint pt);
    afx_msg void OnMouseHWheel(UINT nFlags, short zDelta, CPoint pt);
    afx_msg void OnLButtonDown(UINT nFlags, CPoint point);
    afx_msg void OnLButtonUp(UINT nFlags, CPoint point);
    afx_msg void OnRButtonDown(UINT nFlags, CPoint point);
    afx_msg void OnRButtonUp(UINT nFlags, CPoint point);
    afx_msg void OnMouseMove(UINT nFlags, CPoint point);
    afx_msg void OnMouseLeave();
    afx_msg void OnCaptureChanged(CWnd* pWnd);
    afx_msg BOOL OnSetCursor(CWnd* pWnd, UINT nHitTest, UINT message);
    DECLARE_MESSAGE_MAP()

private:
    // IToolHost
    CCanvasSurface& Surface() override { return m_surface; }
    void InvalidateImage(const CRect& rcImage) override;
    void InvalidateOverlay() override;
    void NotifyColorPicked(COLORREF color, MouseButton button) override;

    /** @brief 현재 도구 객체 */
    CPaintTool& CurrentTool() { return *m_tools[ToIndex(m_tool)]; }

    /** @brief 그림 (0, 0)이 놓이는 클라이언트 좌표 */
    CPoint ImageOrigin() const;
    /** @brief 클라이언트 좌표 → 그림 좌표 */
    CPoint ClientToImage(CPoint ptClient) const;
    /** @brief 그림 좌표 → 클라이언트 좌표 */
    CRect ImageToClient(const CRect& rcImage) const;

    /** @brief 모니터 DPI에 맞춘 픽셀 수 */
    int Scale(int value) const;

    void BeginStroke(CPoint ptClient, MouseButton button);
    void EndStroke(CPoint ptClient, UINT nFlags);

    /** @brief 마우스가 그림 안이면 도구 커서, 밖이면 화살표를 표시합니다. */
    void ApplyCursor(bool insideImage);

    /** @brief 도구 모양 커서(지우개 사각형)를 표시할 마우스 위치를 갱신합니다. */
    void UpdateHover(CPoint ptClient, bool inside);
    /** @brief 도구 모양 커서가 차지하는 클라이언트 영역 */
    CRect HoverClientRect() const;

    void UpdateScrollBars();
    void ScrollTo(int x, int y);
    void HandleScroll(int bar, UINT nSBCode);

    /** @brief 부모 창에 마우스 위치를 알립니다. */
    void NotifyCursor(CPoint ptImage, bool inside);

    CCanvasSurface m_surface;   ///< 그림
    CCanvasSurface m_backup;    ///< 그리기 시작 직전의 그림 (취소용)

    std::array<std::unique_ptr<CPaintTool>, kToolCount> m_tools; ///< 도구 객체 (도구 종류 순서)
    std::array<int, kToolCount> m_toolSizes{};                    ///< 도구별 굵기
    ToolType m_tool = ToolType::Pencil;
    ShapeFillMode m_fillMode = ShapeFillMode::Outline;
    COLORREF m_primary = RGB(0, 0, 0);
    COLORREF m_secondary = RGB(255, 255, 255);

    bool m_stroking = false;                  ///< 마우스로 그리는 중
    MouseButton m_strokeButton = MouseButton::Left;
    CPoint m_lastImagePt;                     ///< 그리는 중 마지막 마우스 위치 (그림 좌표)

    CPoint m_scroll;                          ///< 스크롤 위치 (px)
    bool m_updatingScrollBars = false;        ///< 스크롤 막대 갱신 중 재진입 방지

    bool m_trackingMouse = false;             ///< WM_MOUSELEAVE 추적 중
    bool m_hoverVisible = false;              ///< 도구 모양 커서 표시 중
    CPoint m_hoverImagePt;                    ///< 도구 모양 커서 위치 (그림 좌표)
};
#pragma once

/**
 * @file CanvasSurface.h
 * @brief 그림 데이터를 담는 32비트 DIB 비트맵
 */

#include <cstdint>
#include <vector>

/**
 * @brief 그림 한 장의 픽셀 데이터.
 *
 * DIB 섹션을 메모리 DC에 선택해 두므로 GDI/GDI+로 그릴 수 있고,
 * 동시에 픽셀 메모리에 직접 접근할 수 있습니다(채우기, 스포이트).
 * 픽셀은 위에서 아래 순서, 0x00RRGGBB 형식입니다.
 */
class CCanvasSurface
{
public:
    CCanvasSurface() = default;
    ~CCanvasSurface();

    CCanvasSurface(const CCanvasSurface&) = delete;
    CCanvasSurface& operator=(const CCanvasSurface&) = delete;

    /**
     * @brief 지정한 크기의 비트맵을 만들고 배경색으로 채웁니다. 기존 내용은 버립니다.
     * @param width 너비(px)
     * @param height 높이(px)
     * @param background 배경색
     * @return 성공하면 true
     */
    bool Create(int width, int height, COLORREF background);

    /** @brief 비트맵을 해제합니다. */
    void Destroy();

    /** @brief 비트맵이 만들어져 있으면 true */
    bool IsValid() const { return m_hBitmap != nullptr; }

    /** @brief 비트맵이 선택된 메모리 DC. 여기에 그리면 그림에 반영됩니다. */
    CDC& GetDC() { return m_dc; }

    /** @brief 그림 크기(px) */
    CSize GetSize() const { return CSize(m_width, m_height); }

    /** @brief 그림 전체 영역 (0, 0, 너비, 높이) */
    CRect GetRect() const { return CRect(0, 0, m_width, m_height); }

    /** @brief 점이 그림 안에 있으면 true */
    bool Contains(CPoint pt) const;

    /**
     * @brief 픽셀 색을 읽습니다.
     * @param pt 그림 좌표. 그림 안이어야 합니다.
     */
    COLORREF GetPixel(CPoint pt);

    /**
     * @brief 시작점과 비슷한 색으로 이어진 영역을 채웁니다 (4방향).
     * @param seed 시작점
     * @param color 채울 색
     * @param tolerance 시작점 색과 R, G, B 각각의 차이가 이 값 이하이면 같은 색으로 봄 (0~255).
     *        앤티에일리어싱된 경계의 옅은 픽셀까지 채우는 데 씁니다.
     * @return 바뀐 영역. 바뀐 픽셀이 없으면 빈 사각형
     */
    CRect FloodFill(CPoint seed, COLORREF color, int tolerance);

    /**
     * @brief 다른 그림의 내용을 그대로 복사합니다. 크기가 다르면 크기도 맞춥니다.
     * @param other 원본
     * @return 성공하면 true
     */
    bool CopyFrom(CCanvasSurface& other);

private:
    /** @brief GDI가 아직 쓰지 않은 그리기를 마치고 픽셀 메모리를 돌려줍니다. */
    uint32_t* Pixels();

    /**
     * @brief 채운 영역 바로 바깥의 앤티에일리어싱 픽셀에서 원래 색 비율만큼을 채울 색으로 바꿉니다.
     *        (채운 뒤 경계에 옅은 테두리가 남지 않게 함)
     * @param filled 픽셀별로 채웠으면 1
     * @param target 채우기 전 시작점 색 (0x00RRGGBB)
     * @param replacement 채울 색 (0x00RRGGBB)
     * @param filledBounds 채운 픽셀을 모두 포함하는 사각형
     */
    void BlendFillEdge(const std::vector<uint8_t>& filled, uint32_t target, uint32_t replacement, const CRect& filledBounds);

    CDC m_dc;                        ///< 비트맵이 선택된 메모리 DC
    HBITMAP m_hBitmap = nullptr;     ///< DIB 섹션
    HGDIOBJ m_hOldBitmap = nullptr;  ///< DC에 원래 선택돼 있던 비트맵
    uint32_t* m_bits = nullptr;      ///< 픽셀 메모리 (DIB 섹션 소유)
    int m_width = 0;
    int m_height = 0;
};
#pragma once

/**
 * @file PaintTypes.h
 * @brief 그리기 기능 전반에서 함께 쓰는 타입과 메시지 정의
 */

/** @brief 그리기 도구 종류. 값은 도구 버튼 순서와 같습니다. */
enum class ToolType
{
    Pencil,      ///< 연필: 앤티에일리어싱 없는 단단한 선
    Brush,       ///< 브러시: 부드러운(앤티에일리어싱) 둥근 선
    Eraser,      ///< 지우개: 색 2로 사각형 도장을 찍음
    Fill,        ///< 채우기(페인트 통): 같은 색 영역을 채움
    ColorPicker, ///< 스포이트: 캔버스에서 색을 집음
    Line,        ///< 직선
    Rectangle,   ///< 사각형
    Ellipse,     ///< 타원
};

/** @brief 도구 개수 */
constexpr int kToolCount = 8;

/** @brief 도구를 배열 인덱스로 바꿉니다. */
constexpr int ToIndex(ToolType tool) { return static_cast<int>(tool); }

/** @brief 도형(사각형, 타원)을 그리는 방식 */
enum class ShapeFillMode
{
    Outline,        ///< 윤곽선만 (그린 색)
    OutlineAndFill, ///< 윤곽선(그린 색) + 채우기(반대 색)
    FillOnly,       ///< 채우기만 (그린 색)
};

/** @brief 그리기에 쓴 마우스 버튼. 왼쪽은 색 1, 오른쪽은 색 2로 그립니다. */
enum class MouseButton
{
    Left,
    Right,
};

/** @brief 도구 하나에 대한 표시 정보 */
struct ToolInfo
{
    const wchar_t* name;  ///< 버튼에 표시할 이름
    const wchar_t* hint;  ///< 상태 표시줄에 표시할 사용법
    bool usesSize;        ///< 굵기 설정을 쓰는지
    bool usesFillMode;    ///< 도형 채우기 설정을 쓰는지
    int defaultSize;      ///< 기본 굵기(px)
};

/**
 * @brief 도구의 표시 정보를 돌려줍니다.
 * @param tool 도구 종류
 * @return 정적 수명의 도구 정보
 */
const ToolInfo& GetToolInfo(ToolType tool);

/**
 * @brief 캔버스 → 부모: 마우스 위치가 바뀜.
 * wParam: 이미지 안이면 1, 밖이면 0. lParam: 이미지 좌표 (GET_X_LPARAM / GET_Y_LPARAM)
 */
constexpr UINT WM_CANVAS_CURSOR = WM_APP + 1;

/**
 * @brief 캔버스 → 부모: 스포이트로 색을 집음.
 * wParam: MouseButton, lParam: COLORREF
 */
constexpr UINT WM_CANVAS_COLORPICKED = WM_APP + 2;

/**
 * @brief 팔레트 → 부모: 사용자가 색 1 또는 색 2를 바꿈.
 * wParam, lParam 없음. 팔레트에서 현재 색을 읽으면 됩니다.
 */
constexpr UINT WM_PALETTE_COLORCHANGED = WM_APP + 3;

