    {
        text.Format(L"%d, %dpx", GET_X_LPARAM(lParam), GET_Y_LPARAM(lParam));
    }
    m_statusBar.SetText(text, StatusCursor, 0);
    return 0;
}

void CMyPaintDlg::UpdateImageSizeStatus()
{
